INSERT INTO fields(name, description) VALUES 
('Frontend', 'Field focusing on building and designing user interfaces for web applications.'),
('Backend', 'Field dealing with server-side logic, APIs, and database management.'),
('Data Science', 'Field involving data analysis, processing, and modeling.'),
('Machine Learning', 'Field focused on building predictive models and machine learning algorithms.'),
('DevOps', 'Field related to automation, deployment, CI/CD, and infrastructure management.')
INSERT INTO topics(field_id, name, description) VALUES 
INSERT INTO levels(name, description) VALUES 
('Intern', 'Entry-level role for students or beginners with basic knowledge who still require close guidance from senior developers.'),
('Fresher', 'New graduate with foundational knowledge, able to handle simple tasks.'),
('Junior', '1–2 years of experience, capable of independently completing tasks of medium complexity.'),
('Middle', '2–3 years of experience, good understanding of assigned modules, and able to support fresher/junior developers.'),
('Senior', 'Over 3–5 years of experience, capable of designing systems, solving complex problems, and leading teams.')
INSERT INTO question_types(name, description) VALUES 
('Single Choice', 'Questions that allow selecting only one correct answer.'),
('Multiple Choice', 'Questions that may have multiple correct answers.'),
('Essay', 'Questions that require a written, open-ended response.')
