INSERT INTO answers(user_id, question_id, question_type_id, content, is_correct, similarity_score, useful_vote, unuseful_vote, is_sample_answer, order_number, created_at) VALUES(1, 1, 1, 'useState is only for class components', false, 0.0, 39, 3, false, 1, '2025-01-01 00:00:00'),
(1, 1, 1, 'useState is a Hook that lets you add state to functional components', true, 0.0, 11, 4, false, 2, '2025-01-01 00:00:00'),
(1, 1, 1, 'Virtual DOM makes React slower than direct DOM manipulation', false, 0.0, 10, 9, false, 3, '2025-01-01 00:00:00'),
(1, 2, 1, 'There is no difference between class and functional components', false, 0.0, 48, 3, false, 1, '2025-01-01 00:00:00'),
(1, 2, 1, 'Virtual DOM minimizes direct DOM manipulation by batching updates', true, 0.0, 39, 2, false, 2, '2025-01-01 00:00:00'),
(1, 2, 1, 'Hooks are deprecated and should not be used', false, 0.0, 47, 4, false, 3, '2025-01-01 00:00:00'),
(1, 3, 1, 'Side effects should be handled in the render method', false, 0.0, 47, 10, false, 1, '2025-01-01 00:00:00'),
(1, 3, 1, 'Functional components use hooks while class components use lifecycle methods', true, 0.0, 44, 5, false, 2, '2025-01-01 00:00:00'),
(1, 3, 1, 'React.memo is used for routing between pages', false, 0.0, 21, 2, false, 3, '2025-01-01 00:00:00'),
(1, 4, 1, 'Lifecycle methods work the same in functional components', false, 0.0, 17, 3, false, 1, '2025-01-01 00:00:00'),
(1, 4, 1, 'Hooks allow using state and lifecycle features in functional components', true, 0.0, 13, 8, false, 2, '2025-01-01 00:00:00'),
(1, 4, 1, 'React doesn''t support code splitting', false, 0.0, 18, 1, false, 3, '2025-01-01 00:00:00'),
(1, 5, 2, 'useEffect handles side effects like data fetching and subscriptions', true, 0.0, 33, 0, false, 1, '2025-01-01 00:00:00'),
(1, 5, 2, 'React.memo prevents unnecessary re-renders by memoizing components', true, 0.0, 42, 7, false, 2, '2025-01-01 00:00:00'),
